query:
CREATE TABLE IF NOT EXISTS schedule_note_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  note_id UUID NOT NULL REFERENCES schedule_notes(id) ON DELETE CASCADE,
  organization_id UUID NOT NULL,
  date DATE NOT NULL,
  content TEXT,
  action TEXT NOT NULL CHECK (action IN ('created', 'updated', 'deleted')),
  changed_by UUID NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_schedule_note_history_note_id ON schedule_note_history(note_id);
CREATE INDEX IF NOT EXISTS idx_schedule_note_history_org_date ON schedule_note_history(organization_id, date);

